"""Own observations from the witnesses listed in sources.json; no source payloads."""

def observation(value, source, location, limitation=''):
    return {'value': value, 'evidence': [{'source_id': source, 'location': location}], 'limitation': limitation}

def count(kind, number, source, location, date, scope, unit='objects', eligibility='reported marked objects', lower_bound=False):
    return dict(object_class=kind, count=number, unit=unit, count_date=date, scope=scope,
                inscription_eligibility=eligibility, lower_bound=lower_bound,
                evidence=[dict(source_id=source, location=location)])

def metadata(**kwargs):
    # Each entry is (yes/partial/no, source, exact location, explanation).
    return {k: dict(availability=v[0], evidence=[dict(source_id=v[1], location=v[2])], explanation=v[3])
            for k, v in kwargs.items()}

