def site(name, state, aliases, primary, location, campaigns, coordinates=None, final=False,
         publications=None, counts=None, meta=None, later=None, problems=None, holding=None, coverage=None):
    return dict(name=name, state=state, aliases=aliases, primary=primary, inspection=location,
                campaigns=campaigns, coordinates=coordinates, final_report=final,
                publications=publications or [], counts=counts or [], metadata=meta or {},
                later=later, problems=problems or [], holding=holding, coverage=coverage)

